from pathlib import Path
import base64

FILES = {'apps/dashboard/context_processors.py': '', 'apps/dashboard/spreadsheet.py': '', 'templates/base.html': '', 'templates/dashboard/mockup_shell.html': 'eyUgZXh0ZW5kcyAiYmFzZS5odG1sIiAlfQo=', 'templates/dashboard/artifact_table.html': ''}

for filename, encoded in FILES.items():
    path = Path(filename)
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        backup = path.with_name(path.name + '.before_v63b.bak')
        if not backup.exists():
            backup.write_text(path.read_text(encoding='utf-8'), encoding='utf-8')
    path.write_bytes(base64.b64decode(encoded))
    print('OK:', filename)

CSS_EXTRA = '/* V63B - hojas de cálculo dentro del SGSI */\n.workbook-tabs {\n    margin-top: 12px;\n}\n\n.tab-buttons {\n    display: flex;\n    gap: 5px;\n    flex-wrap: wrap;\n    margin-bottom: 9px;\n}\n\n.workbook-tab {\n    border: 1px solid #cfd9e3;\n    background: #fff;\n    color: #526b82;\n    border-radius: 4px;\n    padding: 7px 10px;\n    font-size: 10px;\n    cursor: pointer;\n}\n\n.workbook-tab.active {\n    background: #1675d1;\n    border-color: #1675d1;\n    color: #fff;\n}\n\n.workbook-sheet {\n    display: none;\n}\n\n.workbook-sheet.active {\n    display: block;\n}\n\n.spreadsheet-panel {\n    overflow: hidden;\n}\n\n.spreadsheet-scroll {\n    max-height: 68vh;\n    overflow: auto;\n}\n\n.spreadsheet-table {\n    border-collapse: collapse;\n    min-width: 100%;\n    width: max-content;\n    background: #fff;\n}\n\n.spreadsheet-table td {\n    border: 1px solid #cfd6dd;\n    padding: 6px 8px;\n    min-width: 90px;\n    max-width: 420px;\n    font-size: 10px;\n    vertical-align: top;\n    white-space: normal;\n}\n\n.spreadsheet-table tr:first-child td {\n    font-weight: 700;\n    background: #eef2f5;\n    position: sticky;\n    top: 0;\n    z-index: 2;\n}\n'
css_path = Path('static/css/mockup_sgsi.css')
css = css_path.read_text(encoding='utf-8')
marker = '/* V63B - hojas de cálculo dentro del SGSI */'
if marker not in css:
    backup = css_path.with_name(css_path.name + '.before_v63b.bak')
    if not backup.exists():
        backup.write_text(css, encoding='utf-8')
    css_path.write_text(css.rstrip() + '\n\n' + CSS_EXTRA + '\n', encoding='utf-8')
    print('OK: static/css/mockup_sgsi.css')

# Context processor global
settings = Path('config/settings/base.py')
text = settings.read_text(encoding='utf-8')
backup = settings.with_name(settings.name + '.before_v63b.bak')
if not backup.exists():
    backup.write_text(text, encoding='utf-8')
cp = '"apps.dashboard.context_processors.sgsi_navigation",'
if cp not in text:
    anchor = '"django.contrib.messages.context_processors.messages",'
    if anchor not in text:
        raise SystemExit('ERROR: no se encontró messages context processor')
    text = text.replace(anchor, anchor + '\n                ' + cp, 1)
    settings.write_text(text, encoding='utf-8')
    print('OK: context processor global')

# Views
views = Path('apps/dashboard/views.py')
vtext = views.read_text(encoding='utf-8')
backup = views.with_name(views.name + '.before_v63b.bak')
if not backup.exists():
    backup.write_text(vtext, encoding='utf-8')
if 'from .spreadsheet import read_xlsx_preview' not in vtext:
    vtext = vtext.replace('from .selectors import (', 'from .spreadsheet import read_xlsx_preview\n\nfrom .selectors import (', 1)
artifact_fn = '''\n@login_required\ndef artifact_table(request, artifact_id):\n    artifact = get_artifact_file(artifact_id)\n    if artifact is None:\n        raise Http404("Archivo no encontrado.")\n    extension = (artifact.extension or "").lower()\n    if extension not in {"xlsx", "xlsm"}:\n        raise Http404("Este tipo de archivo todavía no dispone de vista tabular.")\n    try:\n        sheets = read_xlsx_preview(artifact.file.path, max_rows=300, max_cols=35)\n    except Exception as exc:\n        raise Http404(f"No fue posible interpretar la hoja de cálculo: {exc}")\n    context = _base_context()\n    context.update({"artifact": artifact, "sheets": sheets})\n    return render(request, "dashboard/artifact_table.html", context)\n\n'''
if 'def artifact_table(' not in vtext:
    pos = vtext.find('\ndef health(')
    if pos == -1:
        raise SystemExit('ERROR: no se encontró health()')
    vtext = vtext[:pos] + '\n' + artifact_fn + vtext[pos:]
views.write_text(vtext, encoding='utf-8')
print('OK: apps/dashboard/views.py')

# URLs
urls = Path('apps/dashboard/urls.py')
utext = urls.read_text(encoding='utf-8')
backup = urls.with_name(urls.name + '.before_v63b.bak')
if not backup.exists():
    backup.write_text(utext, encoding='utf-8')
route = '''    path(\n        "archivos/<uuid:artifact_id>/tabla/",\n        views.artifact_table,\n        name="artifact_table",\n    ),\n'''
if 'name="artifact_table"' not in utext:
    anchor = '    path(\n        "archivos/<uuid:artifact_id>/ver/",'
    if anchor not in utext:
        raise SystemExit('ERROR: no se encontró artifact_view route')
    utext = utext.replace(anchor, route + anchor, 1)
urls.write_text(utext, encoding='utf-8')
print('OK: apps/dashboard/urls.py')

# Selector: reconocer spreadsheet
selectors = Path('apps/dashboard/selectors.py')
stext = selectors.read_text(encoding='utf-8')
backup = selectors.with_name(selectors.name + '.before_v63b.bak')
if not backup.exists():
    backup.write_text(stext, encoding='utf-8')
needle = '                    "is_pdf": (artifact.extension or "").lower() == "pdf",\n'
replacement = needle + '                    "is_spreadsheet": (artifact.extension or "").lower() in {"xlsx", "xlsm"},\n'
if needle in stext and '"is_spreadsheet"' not in stext:
    stext = stext.replace(needle, replacement, 1)
selectors.write_text(stext, encoding='utf-8')
print('OK: apps/dashboard/selectors.py')

# Clause template
clause = Path('templates/dashboard/clause_detail.html')
ctext = clause.read_text(encoding='utf-8')
backup = clause.with_name(clause.name + '.before_v63b.bak')
if not backup.exists():
    backup.write_text(ctext, encoding='utf-8')
old = '''                                        {% if support.match.is_pdf %}\n                                        <a target="_blank" href="{% url 'dashboard:artifact_view' support.match.id %}" class="btn-light">Ver PDF</a>\n                                        {% endif %}\n                                        <a href="{% url 'dashboard:artifact_download' support.match.id %}" class="btn-light">Descargar</a>\n'''
new = '''                                        {% if support.match.is_pdf %}\n                                        <a target="_blank" href="{% url 'dashboard:artifact_view' support.match.id %}" class="btn-light">Ver PDF</a>\n                                        {% endif %}\n                                        {% if support.match.is_spreadsheet %}\n                                        <a href="{% url 'dashboard:artifact_table' support.match.id %}" class="primary-small">Ver tabla</a>\n                                        {% endif %}\n                                        <a href="{% url 'dashboard:artifact_download' support.match.id %}" class="btn-light">Descargar</a>\n'''
if old in ctext:
    ctext = ctext.replace(old, new, 1)
clause.write_text(ctext, encoding='utf-8')
print('OK: templates/dashboard/clause_detail.html')

# Document detail template
doc = Path('templates/dashboard/document_detail.html')
dtext = doc.read_text(encoding='utf-8')
backup = doc.with_name(doc.name + '.before_v63b.bak')
if not backup.exists():
    backup.write_text(dtext, encoding='utf-8')
old = '''                    {% if file.is_pdf %}\n                    <a target="_blank" href="{% url 'dashboard:artifact_view' file.artifact_id %}" class="primary-small">Ver PDF</a>\n                    {% endif %}\n                    <a href="{% url 'dashboard:artifact_download' file.artifact_id %}" class="btn-light">Descargar</a>\n'''
new = '''                    {% if file.is_pdf %}\n                    <a target="_blank" href="{% url 'dashboard:artifact_view' file.artifact_id %}" class="primary-small">Ver PDF</a>\n                    {% endif %}\n                    {% if file.extension == "xlsx" or file.extension == "xlsm" %}\n                    <a href="{% url 'dashboard:artifact_table' file.artifact_id %}" class="primary-small">Ver como tabla</a>\n                    {% endif %}\n                    <a href="{% url 'dashboard:artifact_download' file.artifact_id %}" class="btn-light">Descargar</a>\n'''
if old in dtext:
    dtext = dtext.replace(old, new, 1)
doc.write_text(dtext, encoding='utf-8')
print('OK: templates/dashboard/document_detail.html')

print('')
print('V63B aplicada: una sola interfaz + Excel visible dentro del sistema.')
